class TrieNode {
    val children = arrayOfNulls<TrieNode>(26)
    var isEnd = false
}

class Trie {
    private val root = TrieNode()

    fun insert(word: String) {
        var node = root
        for (c in word) {
            val i = c - 'a'
            if (node.children[i] == null) node.children[i] = TrieNode()
            node = node.children[i]!!
        }
        node.isEnd = true                           // a word ends here
    }

    fun search(word: String): Boolean = findNode(word)?.isEnd == true

    fun startsWith(prefix: String): Boolean = findNode(prefix) != null

    private fun findNode(s: String): TrieNode? {
        var node = root
        for (c in s) {
            node = node.children[c - 'a'] ?: return null
        }
        return node
    }
}
// insert / search / startsWith: O(L)   Space: O(total characters * 26) in the worst case

class MapTrieNode {
    val children = HashMap<Char, MapTrieNode>()
    var isEnd = false
}

class MapTrie {
    private val root = MapTrieNode()

    fun insert(word: String) {
        var node = root
        for (c in word) {
            node = node.children.getOrPut(c) { MapTrieNode() }
        }
        node.isEnd = true
    }

    fun search(word: String): Boolean {
        var node = root
        for (c in word) node = node.children[c] ?: return false
        return node.isEnd
    }

    fun startsWith(prefix: String): Boolean {
        var node = root
        for (c in prefix) node = node.children[c] ?: return false
        return true
    }
}
// Same complexity, much less memory when the alphabet is large or sparse

class CountNode {
    val children = arrayOfNulls<CountNode>(26)
    var passCount = 0        // how many words pass through this node (prefix count)
    var endCount = 0         // how many words end exactly here
}

class CountTrie {
    private val root = CountNode()

    fun insert(word: String) {
        var node = root
        for (c in word) {
            val i = c - 'a'
            if (node.children[i] == null) node.children[i] = CountNode()
            node = node.children[i]!!
            node.passCount++
        }
        node.endCount++
    }

    fun countWordsEqualTo(word: String): Int = find(word)?.endCount ?: 0

    fun countWordsStartingWith(prefix: String): Int = find(prefix)?.passCount ?: 0

    fun erase(word: String) {                       // assumes the word exists
        var node = root
        for (c in word) {
            node = node.children[c - 'a']!!
            node.passCount--
        }
        node.endCount--
    }

    private fun find(s: String): CountNode? {
        var node = root
        for (c in s) node = node.children[c - 'a'] ?: return null
        return node
    }
}
// All operations: O(L)

// Used by several examples below
fun insertInto(root: TrieNode, word: String) {
    var node = root
    for (c in word) {
        val i = c - 'a'
        if (node.children[i] == null) node.children[i] = TrieNode()
        node = node.children[i]!!
    }
    node.isEnd = true
}

class WordDictionary {
    private class Node {
        val next = arrayOfNulls<Node>(26)
        var isEnd = false
    }

    private val root = Node()

    fun addWord(word: String) {
        var node = root
        for (c in word) {
            val i = c - 'a'
            if (node.next[i] == null) node.next[i] = Node()
            node = node.next[i]!!
        }
        node.isEnd = true
    }

    fun search(word: String): Boolean {
        fun dfs(node: Node, i: Int): Boolean {
            if (i == word.length) return node.isEnd
            val c = word[i]
            if (c == '.') {                              // try every child
                for (child in node.next) {
                    if (child != null && dfs(child, i + 1)) return true
                }
                return false
            }
            val child = node.next[c - 'a'] ?: return false
            return dfs(child, i + 1)
        }
        return dfs(root, 0)
    }
}
// addWord: O(L)   search: O(L) without dots, O(26^dots * L) worst case

fun longestCommonPrefix(strs: Array<String>): String {
    if (strs.isEmpty()) return ""
    val root = TrieNode()
    for (s in strs) insertInto(root, s)

    val sb = StringBuilder()
    var node = root
    while (true) {
        var count = 0
        var index = -1
        for (i in 0 until 26) {
            if (node.children[i] != null) { count++; index = i }
        }
        if (count != 1 || node.isEnd) break              // branch or a word ends: stop
        sb.append('a' + index)
        node = node.children[index]!!
    }
    return sb.toString()
}
// Time: O(total characters)   Space: O(total characters)
// A simple vertical scan also works in O(total characters) with O(1) space

fun replaceWords(dictionary: List<String>, sentence: String): String {
    val root = TrieNode()
    for (word in dictionary) insertInto(root, word)

    fun shortestRoot(word: String): String {
        var node = root
        for ((i, c) in word.withIndex()) {
            node = node.children[c - 'a'] ?: return word     // no root matches
            if (node.isEnd) return word.substring(0, i + 1)  // first root found
        }
        return word
    }

    return sentence.split(" ").joinToString(" ") { shortestRoot(it) }
}
// Time: O(total characters)   Space: O(dictionary characters)

class WsNode {
    val children = arrayOfNulls<WsNode>(26)
    var word: String? = null              // full word stored at the end node
}

fun findWords(board: Array<CharArray>, words: Array<String>): List<String> {
    val root = WsNode()
    for (w in words) {
        var node = root
        for (c in w) {
            val i = c - 'a'
            if (node.children[i] == null) node.children[i] = WsNode()
            node = node.children[i]!!
        }
        node.word = w
    }

    val result = mutableListOf<String>()
    val rows = board.size
    val cols = board[0].size

    fun dfs(r: Int, c: Int, parent: WsNode) {
        val ch = board[r][c]
        val node = parent.children[ch - 'a'] ?: return          // no word has this prefix
        node.word?.let {
            result.add(it)
            node.word = null                                    // avoid duplicates
        }
        board[r][c] = '#'                                       // mark visited
        if (r > 0 && board[r - 1][c] != '#') dfs(r - 1, c, node)
        if (r < rows - 1 && board[r + 1][c] != '#') dfs(r + 1, c, node)
        if (c > 0 && board[r][c - 1] != '#') dfs(r, c - 1, node)
        if (c < cols - 1 && board[r][c + 1] != '#') dfs(r, c + 1, node)
        board[r][c] = ch                                        // backtrack
        // prune: remove exhausted branches so later searches are faster
        if (node.word == null && node.children.all { it == null }) {
            parent.children[ch - 'a'] = null
        }
    }

    for (r in 0 until rows) for (c in 0 until cols) dfs(r, c, root)
    return result
}
// Time: O(rows * cols * 4 * 3^(L - 1)) worst case   Space: O(total characters)
// One trie lets you search all words in a single board traversal

class SuggestNode {
    val children = arrayOfNulls<SuggestNode>(26)
    val top = ArrayList<String>(3)                  // up to 3 smallest words with this prefix
}

fun suggestedProducts(products: Array<String>, searchWord: String): List<List<String>> {
    products.sort()                                 // insertion order is lexicographic
    val root = SuggestNode()
    for (p in products) {
        var node = root
        for (c in p) {
            val i = c - 'a'
            if (node.children[i] == null) node.children[i] = SuggestNode()
            node = node.children[i]!!
            if (node.top.size < 3) node.top.add(p)
        }
    }

    val result = mutableListOf<List<String>>()
    var node: SuggestNode? = root
    for (c in searchWord) {
        node = node?.children?.get(c - 'a')         // becomes null once the prefix is not found
        result.add(node?.top ?: emptyList())
    }
    return result
}
// Time: O(total characters + L)   Space: O(total characters)

class MapSum {
    private class Node {
        val children = arrayOfNulls<Node>(26)
        var sum = 0                                  // sum of values of all keys with this prefix
    }

    private val root = Node()
    private val values = HashMap<String, Int>()

    fun insert(key: String, value: Int) {
        val delta = value - (values[key] ?: 0)      // handles overwriting an existing key
        values[key] = value
        var node = root
        for (c in key) {
            val i = c - 'a'
            if (node.children[i] == null) node.children[i] = Node()
            node = node.children[i]!!
            node.sum += delta
        }
    }

    fun sum(prefix: String): Int {
        var node = root
        for (c in prefix) node = node.children[c - 'a'] ?: return 0
        return node.sum
    }
}
// insert / sum: O(L)

fun longestWord(words: Array<String>): String {
    val root = TrieNode()
    for (w in words) insertInto(root, w)

    var best = ""
    fun dfs(node: TrieNode, path: StringBuilder) {
        if (path.length > best.length) best = path.toString()   // strictly longer keeps the smallest tie
        for (i in 0 until 26) {                                  // a to z gives lexicographic order
            val child = node.children[i] ?: continue
            if (!child.isEnd) continue                           // every prefix must be a word
            path.append('a' + i)
            dfs(child, path)
            path.deleteCharAt(path.length - 1)
        }
    }

    dfs(root, StringBuilder())
    return best
}
// Time: O(total characters)   Space: O(total characters)

class BitNode {
    val children = arrayOfNulls<BitNode>(2)
}

fun findMaximumXOR(nums: IntArray): Int {
    val root = BitNode()
    for (num in nums) {                               // insert 31 bits, most significant first
        var node = root
        for (bit in 30 downTo 0) {
            val b = (num shr bit) and 1
            if (node.children[b] == null) node.children[b] = BitNode()
            node = node.children[b]!!
        }
    }

    var best = 0
    for (num in nums) {
        var node = root
        var xor = 0
        for (bit in 30 downTo 0) {
            val b = (num shr bit) and 1
            val want = 1 - b                          // the opposite bit gives a 1 in the XOR
            val opposite = node.children[want]
            if (opposite != null) {
                xor = xor or (1 shl bit)
                node = opposite
            } else {
                node = node.children[b]!!
            }
        }
        best = maxOf(best, xor)
    }
    return best
}
// Time: O(32 * n)   Space: O(32 * n)
// Assumes non-negative numbers

class StreamChecker(words: Array<String>) {
    private class Node {
        val children = arrayOfNulls<Node>(26)
        var isEnd = false
    }

    private val root = Node()
    private val stream = StringBuilder()
    private var maxLen = 0

    init {
        for (w in words) {
            maxLen = maxOf(maxLen, w.length)
            var node = root
            for (i in w.indices.reversed()) {              // insert each word reversed
                val idx = w[i] - 'a'
                if (node.children[idx] == null) node.children[idx] = Node()
                node = node.children[idx]!!
            }
            node.isEnd = true
        }
    }

    fun query(letter: Char): Boolean {
        stream.append(letter)
        var node = root
        // walk backward through the most recent characters
        var i = stream.length - 1
        var steps = 0
        while (i >= 0 && steps < maxLen) {
            node = node.children[stream[i] - 'a'] ?: return false
            if (node.isEnd) return true                    // a word is a suffix of the stream
            i--
            steps++
        }
        return false
    }
}
// query: O(maxLen)   Space: O(total characters + stream length)

fun prefixCountDemo(words: List<String>, prefix: String): Int {
    val trie = CountTrie()
    for (w in words) trie.insert(w)
    return trie.countWordsStartingWith(prefix)
}
// Build: O(total characters)   Each query: O(L)
// Without a trie each query would scan all words: O(N * L)

fun autocomplete(root: TrieNode, prefix: String, limit: Int): List<String> {
    var node = root
    for (c in prefix) node = node.children[c - 'a'] ?: return emptyList()

    val result = mutableListOf<String>()
    val path = StringBuilder(prefix)

    fun dfs(cur: TrieNode) {
        if (result.size == limit) return
        if (cur.isEnd) result.add(path.toString())
        for (i in 0 until 26) {                            // alphabetical order
            val child = cur.children[i] ?: continue
            path.append('a' + i)
            dfs(child)
            path.deleteCharAt(path.length - 1)
        }
    }

    dfs(node)
    return result
}
// Time: O(L + size of the explored subtree)   Space: O(depth)
